        await u.request("products", { name_ja: "Forbidden" }, "POST", {
          "idempotency-key": randomUUID(),
        })
      ).statusCode,
    ).toBe(403);
    expect(
      (
        await u.request(
          "users/" + f.bootstrap.id + "/roles",
          { roles: ["Administrator"] },
