});
it("C08 C29 C35 scope revocation changes existing session and invalidates its cursor", async () => {
  await f.create("warehouses", {
    code: "SECOND-GLOBAL",
    name: "Second",
    type: "fba",
  });
  const u = await catalogUser(f, ["Manager"], f.warehouse.id);
